<script setup>
import { computed, ref } from 'vue';
const props = defineProps({ items:{type:Array,default:()=>[]}, reproduciendoId:{type:[Number,String],default:null}, completado:{type:Boolean,default:false} });
const emit = defineEmits(['reproducir','hablar','practicar']);
const leccion=ref(1), sujetoId=ref('i'), verboId=ref('check'), frecuencia=ref('every morning'), verboActivo=ref('study'), retoActual=ref(0), respuestaElegida=ref(null), aciertos=ref(new Set());
const sujetos=[{id:'i',texto:'I',icono:'🙋',tercera:false},{id:'you',texto:'You',icono:'👉',tercera:false},{id:'she',texto:'She',icono:'👩',tercera:true},{id:'he',texto:'He',icono:'👨',tercera:true},{id:'we',texto:'We',icono:'👥',tercera:false},{id:'they',texto:'They',icono:'👨‍👩‍👧',tercera:false},{id:'server',texto:'The server',icono:'🖥️',tercera:true}];
const verbos=[{id:'check',base:'check',tercera:'checks',objeto:'emails',icono:'📧',regla:'+ s'},{id:'work',base:'work',tercera:'works',objeto:'from home',icono:'🏠',regla:'+ s'},{id:'watch',base:'watch',tercera:'watches',objeto:'the dashboard',icono:'📊',regla:'+ es'},{id:'go',base:'go',tercera:'goes',objeto:'to the office',icono:'🏢',regla:'+ es'},{id:'study',base:'study',tercera:'studies',objeto:'English',icono:'📚',regla:'y → ies'},{id:'fix',base:'fix',tercera:'fixes',objeto:'bugs',icono:'🐛',regla:'+ es'},{id:'have',base:'have',tercera:'has',objeto:'a meeting',icono:'🗓️',regla:'irregular'}];
const sujeto=computed(()=>sujetos.find(x=>x.id===sujetoId.value)),verbo=computed(()=>verbos.find(x=>x.id===verboId.value)),demostracion=computed(()=>verbos.find(x=>x.id===verboActivo.value));
const frase=computed(()=>`${sujeto.value.texto} ${sujeto.value.tercera?verbo.value.tercera:verbo.value.base} ${verbo.value.objeto} ${frecuencia.value}.`);
const retos=[
{icono:'👩',frase:'She ___ every pull request.',respuesta:'reviews',opciones:['review','reviews','reviewing','reviewed'],explicacion:'She es tercera persona: review + s.'},
{icono:'👥',frase:'They ___ from home on Fridays.',respuesta:'work',opciones:['works','work','working','worked'],explicacion:'Con they usamos la forma base.'},
{icono:'❓',frase:'___ he check the logs every day?',respuesta:'Does',opciones:['Do','Does','Is','Are'],explicacion:'Does acompaña a he/she/it en preguntas.'},
{icono:'🚫',frase:"The server ___ passwords in plain text.",respuesta:"doesn't store",opciones:["doesn't store","don't store","isn't store","not stores"],explicacion:"Después de doesn't el verbo vuelve a la forma base."},
{icono:'📚',frase:'Maya ___ English after work.',respuesta:'studies',opciones:['study','studys','studies','studying'],explicacion:'Consonante + y cambia a -ies.'}];
const reto=computed(()=>retos[retoActual.value]),correcta=computed(()=>respuestaElegida.value===reto.value.respuesta),total=computed(()=>aciertos.value.size);
function norm(t){return String(t||'').toLowerCase().replace(/[^a-z]/g,'')}function escuchar(t){const i=props.items.find(x=>norm(x.texto_en)===norm(t));if(i?.audio_key)emit('reproducir',i);else emit('hablar',t,1)}
function responder(o){respuestaElegida.value=o;if(o===reto.value.respuesta){const n=new Set(aciertos.value);n.add(retoActual.value);aciertos.value=n}}function siguiente(){retoActual.value=(retoActual.value+1)%retos.length;respuestaElegida.value=null}
</script>
<template><section class="ps-lesson">
<aside class="ps-summary"><header><span>🔁</span><div><small>MAPA RÁPIDO</small><h2>Presente simple = lo habitual</h2></div></header><p>Usalo para <b>rutinas</b>, <b>hábitos</b> y <b>hechos generales</b>. Solo cambia el verbo con <b>he, she, it</b>.</p><div><article><b>I / you / we / they</b><span>work · study · go</span></article><article><b>he / she / it</b><span>works · studies · goes</span></article><article><b>Pregunta</b><span>Do…? / Does…?</span></article><article><b>Negación</b><span>don't / doesn't + base</span></article></div></aside>
<nav class="ps-tabs"><button v-for="n in 3" :key="n" :class="{active:leccion===n}" @click="leccion=n"><b>0{{n}}</b><span>{{n===1?'Construí una rutina':n===2?'La tercera persona':'Do o does?'}}</span><small>{{n===1?'sujeto + hábito + tiempo':n===2?'s · es · ies':'preguntas y negación'}}</small></button></nav>
<section v-if="leccion===1" class="ps-panel"><header><small>PRESENTE SIMPLE 1</small><h3>Constructor de rutinas</h3><p>Combiná quién, qué hace y cuándo.</p></header><div class="routine-builder"><div class="subject-row"><button v-for="x in sujetos" :key="x.id" :class="{active:sujetoId===x.id}" @click="sujetoId=x.id"><span>{{x.icono}}</span><b>{{x.texto}}</b></button></div><div class="verb-row"><button v-for="x in verbos" :key="x.id" :class="{active:verboId===x.id}" @click="verboId=x.id"><span>{{x.icono}}</span><b>{{x.base}}</b></button></div><select v-model="frecuencia"><option>every morning</option><option>every day</option><option>on Mondays</option><option>after work</option><option>once a week</option></select></div><div class="routine-result"><span>{{sujeto.icono}} {{verbo.icono}}</span><small>MI RUTINA</small><strong>{{frase}}</strong><button @click="escuchar(frase)">🔊 Escuchar</button></div></section>
<section v-else-if="leccion===2" class="ps-panel"><header><small>PRESENTE SIMPLE 2</small><h3>La máquina de la tercera persona</h3><p>Tocá un verbo para ver qué ocurre con he, she o it.</p></header><div class="third-person-lab"><div class="verb-cards"><button v-for="x in verbos" :key="x.id" :class="{active:verboActivo===x.id}" @click="verboActivo=x.id"><span>{{x.icono}}</span><b>{{x.base}}</b></button></div><div class="transformer"><small>FORMA BASE</small><b>{{demostracion.base}}</b><i>＋ {{demostracion.regla }}</i><span>→</span><small>HE / SHE / IT</small><strong>{{demostracion.tercera}}</strong><button @click="escuchar(`She ${demostracion.tercera} ${demostracion.objeto}.`)">🔊 She {{demostracion.tercera}} {{demostracion.objeto}}.</button></div></div><div class="rule-cards"><article><b>Normal</b><span>work → works</span></article><article><b>-ch, -sh, -x, -o</b><span>watch → watches</span></article><article><b>consonante + y</b><span>study → studies</span></article><article><b>Irregular</b><span>have → has</span></article></div></section>
<section v-else class="ps-panel"><header class="ps-challenge-head"><div><small>PRESENTE SIMPLE 3</small><h3>Radar de hábitos</h3><p>Elegí la forma correcta para cada rutina.</p></div><strong>{{total}}/{{retos.length}}</strong></header><div class="ps-challenge"><span>{{reto.icono}}</span><button @click="escuchar(reto.frase.replace('___',reto.respuesta))">{{reto.frase}} 🔊</button><div><button v-for="o in reto.opciones" :key="o" :class="{correct:respuestaElegida&&o===reto.respuesta,wrong:respuestaElegida===o&&o!==reto.respuesta}" :disabled="correcta" @click="responder(o)">{{o}}</button></div><p v-if="respuestaElegida" :class="correcta?'ok':'retry'"><b>{{correcta?'✓ ¡Rutina correcta!':'↻ Revisá el sujeto'}}</b><span>{{reto.explicacion}}</span></p><button v-if="correcta" class="next" @click="siguiente">Siguiente rutina →</button></div></section>
<button class="ps-practice" :disabled="completado" @click="emit('practicar')">{{completado?'✓ Ejercicios ya acreditados':'Practicar ejercicios del workbook →'}}</button></section></template>
