ong{border-color:#c96543;background:#fff0ea}.ps-challenge>p{display:flex;flex-direction:column;padding:.6rem;border-radius:9px;text-align:left;font-size:.75rem}.ps-challenge>p.ok{background:var(--color-verde-suave)}.ps-challenge>p.retry{background:#fff0ea}.next{margin-left:auto!important;background:#168c78!important;color:#fff!important;padding:.55rem .8rem!important}.ps-practice{width:100%;padding:.8rem;border:0;border-radius:var(--radio-boton);background:#168c78;color:#fff;font-weight:800}.ps-practice:disabled{background:var(--color-verde)}
